// MOTION_GATE: absent on the record instead of a finding.
if (checkReport.ran !== true && ['mp4', 'gif', 'webp'].indexOf(field(a.FORMAT).toLowerCase()) !== -1) {
  addDerived({ id: 'Xcheck-absent', severity: 2, where: 'the render',
    what: 'the deterministic gate did not run: ' + (field(checkReport.reason) || 'no reason recorded'),
    fix: 'make the check run for this artifact' });
}
for (const entry of derived.values()) {
  const at = open.findIndex((f) => f.id === entry.id);
  if (at !== -1) open.splice(at, 1, entry);
  else open.push(entry);
}
const ledger = unreadable ? prev.slice() : open;
const verdict = unreadable ? 'unread' : (open.length ? 'fix' : 'ok');
const stalled = ledger.filter((f) => Number(f.seen || 0) >= 2).map((f) => field(f.id));
// A stalled finding does not spend another turn, whatever its source: the budget is for
// something the composer has not already been told once.
const retry = !unreadable && open.some((f) => Number(f.seen || 0) === 1) && round < cycles;
const findingsText = ledger.slice().sort(rank).map((f, i) => (i + 1) + '. [' + field(f.id) + ' severity '
  + severityOf(f.severity) + '] where: ' + (field(f.where) || 'not named') + ' what: '
  + (field(f.what) || 'a defect') + ' fix: ' + (field(f.fix) || 'no change named')).join('\n');
return [{ json: {
  ...a,
  VERDICT: verdict,
  OPEN_FINDINGS: JSON.stringify(ledger),
  STALLED: JSON.stringify(stalled),
  NEEDS_REVIEW: unreadable || open.length > 0,
  RETRY: retry,
  FINDINGS_TEXT: findingsText,
  UNREADABLE: unreadable,
  REVIEW_REASON: unreadable ? 'the critic did not answer, or its answer could not be read' : '',
  REVIEW: JSON.stringify({ round: round + 1, verdict, resolved: resolvedGiven, open: ledger,
    stalled, unreadable, raw: raw.slice(0, 2000) }),
} }];

// The next authoring turn, with the critic's findings as the reviewer's correction. The
// session id is unchanged, so the adapter edits the composition in place rather than
// authoring a new one, and the round is incremented for the bound the gate reads.
const a = $input.first().json;
const text = String(a.FINDINGS_TEXT || '').trim();
return [{ json: {
  ...a,
  HUMAN_FEEDBACK: a.HUMAN_FEEDBACK || '',
  FEEDBACK: text ? text + '\nThese findings are still open; do not regress them.' : '',
  REVIEW_ROUND: Math.max(0, Number(a.REVIEW_ROUND || 0)) + 1,
} }];

// The raster's review request, from the bytes this execution already holds. A raster is made
// inside n8n (no store can fetch bytes n8n created), so unlike an authored composition there is
// nothing to fetch back and no still to make: the data URL the image model returned is what the
// critic looks at. A render that produced no image is not reviewed, and says so.
const a = $input.first().json || {};
const round = Math.max(0, Number(a.RASTER_REVIEW_ROUND || 0));
const prompt = String($('download_raster_review_prompt').first().json.output || '').trim();
const image = String(a.IMAGE || '');
const reason = !prompt ? 'the review prompt is empty' : !image ? 'the image model returned no image' : '';
if (reason) {
  // The ledger it came in with stays open: an asset is never unreviewed and unmarked at once.
  return [{ json: { ...a, RASTER_REVIEW_ROUND: round, REVIEWED: false, REVIEW_REASON: reason, CRITIQUE_BODY: '',
    VERDICT: 'unread', NEEDS_REVIEW: true, RETRY: false } }];
}
const text = [
  prompt,
  '---',
  'The image prompt this was generated from:',
  String(a.PROMPT || '(not recorded)'),
  '---',
  'The source text it illustrates:',
  String(a.CONTENT || ''),
].join('\n\n');
return [{ json: {
  ...a,
  RASTER_REVIEW_ROUND: round,
  REVIEWED: true,
  CRITIQUE_BODY: JSON.stringify({ model: 'opencode-go/glm-5.3-flash', messages: [{ role: 'user', content: [
    { type: 'text', text },
    { type: 'image_url', image_url: { url: image } },
  ] }] }),
} }];

// The same ledger as the composition half, over a raster's findings: an unreadable answer is
// not a pass, and a finding keeps its id, severity and count across prompt rewrites.
const resp = $input.first().json || {};
const a = $('prepare_raster_review').first().json;
const raw = String((((resp.choices || [])[0] || {}).message || {}).content || '').trim();
const round = Math.max(0, Number(a.RASTER_REVIEW_ROUND || 0));
const cycles = Math.max(0, Number($('normalize_input').first().json.REVIEW_CYCLES || 0));
const field = (v) => String(v == null ? '' : v).trim();
const severityOf = (v) => {
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= 3 ? n : 2;
};
const rank = (x, y) => severityOf(x.severity) - severityOf(y.severity)
  || String(x.id || '').localeCompare(String(y.id || ''), 'en', { numeric: true });
const normal = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const prev = (() => {
  try {
    const parsed = JSON.parse(String(a.OPEN_FINDINGS || '[]'));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) { return []; }
})();
// Tolerant: the first object in the answer. No object at all, or an answer that says it could
// not see the image, is `unread` and leaves the ledger exactly as it came in.
let answer = null;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end > start) {
  try {
    const parsed = JSON.parse(raw.slice(start, end + 1));
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) answer = parsed;
  } catch (e) { answer = null; }
}
const verdictWord = answer ? field(answer.verdict).toLowerCase() : '';
// Ids are matched case-insensitively (`F1` and `f1` are one finding); the ledger keeps the
// casing the id was first stored with.
const resolvedGiven = (answer && Array.isArray(answer.resolved) ? answer.resolved : []).map(field);
const resolved = new Set(resolvedGiven.map((v) => v.toUpperCase()));
const reported = new Map();
const fresh = [];
if (answer && Array.isArray(answer.findings)) {
  for (const f of answer.findings) {
    if (!f || typeof f !== 'object') continue;
    const entry = { severity: severityOf(f.severity), where: field(f.where), what: field(f.what), fix: field(f.fix) };
    if (!entry.what && !entry.fix) continue;
    const id = field(f.id);
    if (id) reported.set(id.toUpperCase(), entry);
    else fresh.push(entry);
  }
}
// No verdict we can act on and nothing merged is not an answer: it cannot pass as one.
const unreadable = !answer || verdictWord === 'unread'
  || (!['ok', 'fix', 'unread'].includes(verdictWord) && !reported.size && !fresh.length);
let maxId = 0;
for (const f of prev) {
  const m = /^F(\d+)$/.exec(field(f && f.id));
  if (m) maxId = Math.max(maxId, Number(m[1]));
}
const open = [];
const recounted = new Set();
const prevIds = new Set();
for (const f of prev) {
  const id = field(f && f.id);
  if (!id) continue;
  const key = id.toUpperCase();
  prevIds.add(key);
  if (resolved.has(key)) continue;
  const again = reported.get(key);
  // Silence is not a fix: an id neither resolved nor re-reported stays open at its count.
  if (!again) { open.push(f); continue; }
  recounted.add(key);
  open.push({ id, severity: again.severity, where: again.where, what: again.what, fix: again.fix,
    seen: Number(f.seen || 0) + 1, source: f.source || 'critic' });
}
const byText = new Map();
for (const f of open) {
  const key = normal((f.where || '') + '|' + (f.what || ''));
  if (key !== '|' && !byText.has(key)) byText.set(key, f);
}
// An id the ledger does not know is a new defect the critic reported with a stale id, so it is
// allocated the next free F<n>; a defect already open at the same place and words keeps its id.
const addNew = (entry) => {
  const key = normal(entry.where + '|' + entry.what);
  const same = key === '|' ? undefined : byText.get(key);
  if (same) {
    const idKey = field(same.id).toUpperCase();
    if (!recounted.has(idKey)) { same.seen = Number(same.seen || 0) + 1; recounted.add(idKey); }
    if (!same.fix && entry.fix) same.fix = entry.fix;
    return;
  }
  const item = { id: 'F' + (++maxId), severity: entry.severity, where: entry.where, what: entry.what,
    fix: entry.fix, seen: 1, source: 'critic' };
  open.push(item);
  if (key !== '|') byText.set(key, item);
  recounted.add(item.id.toUpperCase());
};
for (const [id, entry] of reported) {
  if (!prevIds.has(id)) addNew(entry);
}
for (const entry of fresh) addNew(entry);
const ledger = unreadable ? prev.slice() : open;
const verdict = unreadable ? 'unread' : (open.length ? 'fix' : 'ok');
const stalled = ledger.filter((f) => Number(f.seen || 0) >= 2).map((f) => field(f.id));
// A stalled finding does not spend another turn, whatever its source: the budget is for
// something the prompt writer has not already been told once.
const retry = !unreadable && open.some((f) => Number(f.seen || 0) === 1) && round < cycles;
const findingsText = ledger.slice().sort(rank).map((f, i) => (i + 1) + '. [' + field(f.id) + ' severity '
  + severityOf(f.severity) + '] where: ' + (field(f.where) || 'not named') + ' what: '
  + (field(f.what) || 'a defect') + ' fix: ' + (field(f.fix) || 'no change named')).join('\n');
return [{ json: {
  ...a,
  VERDICT: verdict,
  OPEN_FINDINGS: JSON.stringify(ledger),
  STALLED: JSON.stringify(stalled),
  NEEDS_REVIEW: unreadable || open.length > 0,
  RETRY: retry,
  FINDINGS_TEXT: findingsText,
  UNREADABLE: unreadable,
  REVIEW_REASON: unreadable ? 'the critic did not answer, or its answer could not be read' : '',
  REVIEW: JSON.stringify({ round: round + 1, verdict, resolved: resolvedGiven, open: ledger,
    stalled, unreadable, raw: raw.slice(0, 2000) }),
} }];

// The fix for a raster is a rewritten image prompt, so the finding goes back to the prompt
// writer: `visual_raster.md` already carries the reviewer's feedback block, and re-fetching it
// with this feedback is what puts the change into the next prompt. The round is incremented for
// the bound the gate reads.
const a = $input.first().json;
const text = String(a.FINDINGS_TEXT || '').trim();
return [{ json: {
  ...a,
  FEEDBACK: text ? text + '\nThese findings are still open; do not regress them.' : '',
  RASTER_REVIEW_ROUND: Math.max(0, Number(a.RASTER_REVIEW_ROUND || 0)) + 1,
} }];

// prompts/visual_scene.md is the one copy of the scene contract. It is fetched once and
// handed to build_author_brief, which appends it to every scene-bearing brief.
return [{ json: { SCENE: String($json.output || '') } }];
